+    }
+    visiting.add(name);
+    const extension = byName.get(name)!;
+    for (const dependency of extension.dependencies ?? []) visit(dependency, [...path, name]);
+    visiting.delete(name);
+    visited.add(name);
+    ordered.push(extension);
+  };
