+      }
+      let current = document;
+      let version = fromVersion;
+      while (version < toVersion) {
+        const migrations = ordered
+          .flatMap((extension) => extension.migrations ?? [])
+          .filter((migration) => migration.from === version)
+          .sort((a, b) => a.to - b.to);
