+            "MDFN_SCHEMA_MIGRATION_MISSING",
+            `No schema migration from version ${version} to ${toVersion}`,
+          );
+        }
+        current = next.migrate(current);
+        version = next.to;
+      }
+      return current;
+    },
+  };
